  private static async adapt(config: InternalAxiosRequestConfig): Promise<AxiosResponse<Object>> {
    const event = new LocalRequestEvent();
    event.sequence = LocalBaselineFixture.requests.length + 1;
    event.method = (config.method ?? 'GET').toUpperCase();
    event.path = (config.url ?? '').replace(/^\/+/, '').split('?')[0];
    event.body = typeof config.data === 'string' ? config.data : JSON.stringify(config.data) ?? '';
    event.hasAuthorization = Boolean(config.headers.get('Authorization'));
    LocalBaselineFixture.requests.push(event);
    let payload: Object;
    if (event.method === 'GET' && event.path === 'page/confirmOrder') {
      LocalBaselineFixture.confirmCount++;
      await new Promise<void>((resolve) => { setTimeout(resolve, 150); });
      payload = LocalBaselineFixture.successful(LocalBaselineFixture.confirmData());
      event.outcome = 'LOCAL_CONFIRM_FIXTURE';
    } else if (event.method === 'POST' && event.path === 'user/address/page') {
      LocalBaselineFixture.addressPageCount++;
      const page = new NetworkPageData<Address>();
      page.list = LocalBaselineFixture.addresses.slice();
      const pagination = new NetworkPageMeta();
      pagination.page = 1;
      pagination.size = 10;
      pagination.total = page.list.length;
      page.pagination = pagination;
      payload = LocalBaselineFixture.successful(page);
      event.outcome = 'LOCAL_ADDRESS_LIST_FIXTURE';
    } else if (event.method === 'POST' && event.path === 'user/address/add') {
      LocalBaselineFixture.addressAddCount++;
      const parsed = JSON.parse(event.body) as Address;
      const address = new Address(parsed);
      address.id = LocalBaselineFixture.nextAddressId++;
      LocalBaselineFixture.addresses.push(address);
      const data: Record<string, number> = { 'id': address.id };
      payload = LocalBaselineFixture.successful(data);
      event.outcome = 'LOCAL_ADDRESS_ADD_FIXTURE';
    } else {
      if (event.method === 'POST' && event.path === 'order/info/create') {
        LocalBaselineFixture.createCount++;
        event.outcome = 'LOCAL_CREATE_REJECTED_NO_ORDER_CREATED';
      } else {
        event.outcome = 'LOCAL_UNKNOWN_REJECTED';
      }
      LocalBaselineFixture.rejectCount++;
      LocalBaselineFixture.log('REQUEST', JSON.stringify(event));
      throw new Error(`HCUP_LOCAL_ONLY rejected ${event.method} ${event.path}`);
    }
    LocalBaselineFixture.log('REQUEST', JSON.stringify(event));
    const response: AxiosResponse<Object> = {
      data: payload, status: 200, statusText: 'LOCAL_FIXTURE', headers: new AxiosHeaders(), config: config
    };
    return response;
  }

  static async dumpActual(reason: string): Promise<void> {
    const snapshot = new LocalRuntimeSnapshot();
    snapshot.reason = reason;
    snapshot.scenario = LocalBaselineFixture.scenario;
    snapshot.entry = LocalBaselineFixture.entry;
    snapshot.addressListMode = LocalBaselineFixture.emptyAddressList ? 'initially-empty' : 'seeded';
