      payload = LocalBaselineFixture.successful(data);
      event.outcome = 'LOCAL_ADDRESS_ADD_FIXTURE';
    } else {
      if (event.method === 'POST' && event.path === 'order/info/create') {
        LocalBaselineFixture.createCount++;
        event.outcome = 'LOCAL_CREATE_REJECTED_NO_ORDER_CREATED';
      } else {
        event.outcome = 'LOCAL_UNKNOWN_REJECTED';
      }
      LocalBaselineFixture.rejectCount++;
      LocalBaselineFixture.log('REQUEST', JSON.stringify(event));
      throw new Error(`HCUP_LOCAL_ONLY rejected ${event.method} ${event.path}`);
    }
    LocalBaselineFixture.log('REQUEST', JSON.stringify(event));
    const response: AxiosResponse<Object> = {
      data: payload, status: 200, statusText: 'LOCAL_FIXTURE', headers: new AxiosHeaders(), config: config
    };
    return response;
  }

  static async dumpActual(reason: string): Promise<void> {
    const snapshot = new LocalRuntimeSnapshot();
    snapshot.reason = reason;
    snapshot.scenario = LocalBaselineFixture.scenario;
    snapshot.entry = LocalBaselineFixture.entry;
    snapshot.addressListMode = LocalBaselineFixture.emptyAddressList ? 'initially-empty' : 'seeded';
    snapshot.routeNames = getNavPathStack()?.getAllPathName() ?? [];
    snapshot.order = LocalAnalysisProbe.readOrder();
    const cartRepository = new CartRepository();
    snapshot.carts = await cartRepository.getAllCarts();
    const cache = new OrderCacheStoreRepository();
    snapshot.cacheCarts = await cache.loadCarts();
    snapshot.cacheSelectedGoods = await cache.loadSelectedGoodsList();
    snapshot.confirmCount = LocalBaselineFixture.confirmCount;
    snapshot.addressPageCount = LocalBaselineFixture.addressPageCount;
    snapshot.addressAddCount = LocalBaselineFixture.addressAddCount;
    snapshot.createCount = LocalBaselineFixture.createCount;
    snapshot.rejectCount = LocalBaselineFixture.rejectCount;
    snapshot.requests = LocalBaselineFixture.requests;
    // Every record is bounded and reassembled by snapshotId/kind/index/total.
    const snapshotId = `snapshot-${++LocalBaselineFixture.snapshotSequence}`;
    LocalBaselineFixture.log('STATE', JSON.stringify(snapshot), snapshotId);
    LocalBaselineFixture.log('ORDER_ACTUAL', JSON.stringify(snapshot.order), snapshotId);
    LocalBaselineFixture.log('CARTS_ACTUAL', JSON.stringify(snapshot.carts), snapshotId);
    LocalBaselineFixture.log('COUNTS', `confirm=${snapshot.confirmCount};addressPage=${snapshot.addressPageCount};` +
      `addressAdd=${snapshot.addressAddCount};create=${snapshot.createCount};reject=${snapshot.rejectCount};` +
      `routes=${JSON.stringify(snapshot.routeNames)}`, snapshotId);
  }
}
