"""Reassemble bounded HCUP_LOCAL diagnostics; reject incomplete or conflicting records."""
import argparse
import json
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument('hilog', type=Path)
parser.add_argument('output', type=Path)
parser.add_argument('--require-manual', action='store_true')
parser.add_argument('--require-order', action='store_true')
args = parser.parse_args()
groups = {}
errors = []
for number, line in enumerate(args.hilog.read_text(encoding='utf-8', errors='replace').splitlines(), 1):
    marker = '[HCUP_LOCAL] CHUNK '
    if marker not in line:
        continue
    try:
        chunk = json.loads(line.split(marker, 1)[1])
        key = (chunk['runId'], chunk['snapshotId'], chunk['kind'])
        group = groups.setdefault(key, {'total': chunk['total'], 'parts': {}})
        if group['total'] != chunk['total']:
            raise ValueError('inconsistent total')
        index = chunk['index']
        if not 0 <= index < chunk['total']:
            raise ValueError('chunk index outside range')
        if index in group['parts'] and group['parts'][index] != chunk['payload']:
            raise ValueError('conflicting duplicate chunk')
        group['parts'][index] = chunk['payload']
    except (KeyError, ValueError, TypeError) as error:
        errors.append({'line': number, 'error': str(error)})
records = []
for (run_id, snapshot_id, kind), group in groups.items():
    missing = sorted(set(range(group['total'])) - group['parts'].keys())
    if missing:
        errors.append({'runId': run_id, 'snapshotId': snapshot_id, 'kind': kind, 'missing': missing})
        continue
    payload = ''.join(group['parts'][index] for index in range(group['total']))
    try:
        actual = json.loads(payload)
    except ValueError as error:
        actual = payload
        if kind in ('STATE', 'ORDER_ACTUAL', 'CARTS_ACTUAL', 'REQUEST'):
            errors.append({'runId': run_id, 'snapshotId': snapshot_id, 'kind': kind,
                           'invalid_json': str(error)})
    records.append({'runId': run_id, 'snapshotId': snapshot_id, 'kind': kind, 'actual': actual})
states = [record for record in records if record['kind'] == 'STATE' and isinstance(record['actual'], dict)]
if not states:
    errors.append({'required': 'At least one complete JSON STATE record'})
if args.require_manual and not any(state['actual'].get('reason') == 'manual' for state in states):
    errors.append({'required': 'A manual diagnostic STATE snapshot'})
if args.require_order and not any(isinstance(state['actual'].get('order'), dict) for state in states):
    errors.append({'required': 'A STATE snapshot read from the actual order VM'})
for state in states:
    required = {'STATE', 'ORDER_ACTUAL', 'CARTS_ACTUAL', 'COUNTS'}
    found = {record['kind'] for record in records if record['runId'] == state['runId']
             and record['snapshotId'] == state['snapshotId']}
    if not required.issubset(found):
        errors.append({'runId': state['runId'], 'snapshotId': state['snapshotId'],
                       'missing_snapshot_records': sorted(required - found)})
args.output.parent.mkdir(parents=True, exist_ok=True)
args.output.write_text(json.dumps({'records': records, 'errors': errors}, ensure_ascii=False, indent=2) + '\n',
                       encoding='utf-8')
print(json.dumps({'complete_records': len(records), 'errors': len(errors)}))
raise SystemExit(1 if errors else 0)
