EXPECTED = 'bbdd20875c2adade9f2838d393239dbf254046d31fddb8036902e413e88d4c22'


def hdc(*values):
    command = ['hdc', '-t', '127.0.0.1:11243', *map(str, values)]
    r = subprocess.run(command, capture_output=True, encoding='utf-8', errors='replace', timeout=40)
    row = dict(utc=datetime.now(timezone.utc).isoformat(), command=command,
               exit_code=r.returncode, stdout=r.stdout, stderr=r.stderr)
    with (OUT / 'commands.jsonl').open('a', encoding='utf-8') as stream:
        stream.write(json.dumps(row, ensure_ascii=False) + '\n')
    if r.returncode or '[Fail]' in r.stdout:
        raise RuntimeError(row)
    return r.stdout


def snapshot(label):
    for ext, operation in [('png', 'screenCap'), ('json', 'dumpLayout')]:
        remote = f'/data/local/tmp/cml17-do-prod-{label}.{ext}'
        hdc('shell', 'uitest', operation, '-p', remote)
        hdc('file', 'recv', remote, OUT / f'{label}.{ext}')
    (OUT / f'{label}-missions.txt').write_text(hdc('shell', 'aa', 'dump', '-l'), encoding='utf-8')
    pid = hdc('shell', 'pidof', 'com.joker.coolmall').strip()
    (OUT / f'{label}-pid.txt').write_text(pid, encoding='utf-8')
    (OUT / f'{label}-hilog.log').write_text(hdc('shell', 'hilog', '-x', '-P', pid), encoding='utf-8')
    return json.loads((OUT / f'{label}.json').read_text(encoding='utf-8-sig'))


def walk(node):
    if 'attributes' in node:
        yield node['attributes']
    for child in node.get('children', []):
        yield from walk(child)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--run-authorized', action='store_true')
    args = parser.parse_args()
    if not args.run_authorized or hashlib.sha256(HAP.read_bytes()).hexdigest() != EXPECTED:
        raise RuntimeError('Missing serial authorization or unexpected ordinary HAP')
    OUT.mkdir(parents=True, exist_ok=True)
    os.chdir(OUT)
    hdc('install', '-r', HAP)
    (OUT / 'bundle.txt').write_text(hdc('shell', 'bm', 'dump', '-n', 'com.joker.coolmall'), encoding='utf-8')
    hdc('shell', 'aa', 'force-stop', 'com.joker.coolmall')
    hdc('shell', 'aa', 'start', '-a', 'EntryAbility', '-b', 'com.joker.coolmall')
    time.sleep(1.5)
    snapshot('01-cold-start')
    from hypium import UiDriver, BY
    driver = UiDriver.connect(device_sn='127.0.0.1:11243')
    driver.set_implicit_wait_time(1)
    driver.click(BY.key('main_tab_cart'))
    time.sleep(0.5)
    tree = snapshot('02-original-cart')
    choices = [a['id'] for a in walk(tree) if a.get('id', '').startswith('cart_select_')]
    result = dict(hap_sha256=EXPECTED, bundle='com.joker.coolmall', device='127.0.0.1:11243',
                  cold_start='pass', checkout_guard='not_run', authenticated_backend='blocked:no_credentials')
    if choices:
        driver.click(BY.key(choices[0]))
        driver.click(BY.key('cart_settle'))
        time.sleep(1)
        after = snapshot('03-checkout-guard')
        texts = [a.get('text', '') for a in walk(after)]
        raw = (OUT / '03-checkout-guard-hilog.log').read_text(encoding='utf-8')
        assert any('登录' in v for v in texts), 'Checkout did not show the original login UI'
        assert 'Intercepting route to order/confirm' in raw, 'Missing original guard interception log'
        result['checkout_guard'] = 'pass'
    else:
        result['checkout_guard_reason'] = 'Ordinary task app cart is empty; no fabricated production cache'
    (OUT / 'result.json').write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding='utf-8')
    print(json.dumps(result, ensure_ascii=False))


